import java.sql.*;
import java.util.*;

public class Main {
    private static final String URL = "jdbc:mysql://localhost:3306/customerdb";
    private static final String USERNAME = "root";
    private static final String PASSWORD = "";

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
        } catch (ClassNotFoundException e) {
            System.out.println("Driver not found: " + e.getMessage());
            return;
        }

        String operation = sc.nextLine().trim();

        try (Connection conn = DriverManager.getConnection(URL, USERNAME, PASSWORD)) {
            switch (operation) {
                case "insert":
                    handleInsert(conn, sc);
                    break;
                case "update":
                    handleUpdate(conn, sc);
                    break;
                case "delete":
                    handleDelete(conn, sc);
                    break;
                case "display":
                    handleDisplay(conn);
                    break;
                default:
                    System.out.println("Invalid operation");
            }
        } catch (SQLException e) {
            System.out.println("Database error: " + e.getMessage());
        }

        sc.close();
    }

    private static void handleInsert(Connection conn, Scanner sc) throws SQLException {
        String idStr = sc.nextLine().trim();
        String name = sc.nextLine().trim();
        String email = sc.nextLine().trim();
        String phone = sc.nextLine().trim();

        int custId = Integer.parseInt(idStr);

        String sql = "INSERT INTO Contacts (cust_id, name, email, phone) VALUES (?, ?, ?, ?)";
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, custId);
            stmt.setString(2, name);
            stmt.setString(3, email);
            stmt.setString(4, phone);
            stmt.executeUpdate();
        }
        System.out.println("Contact inserted successfully.");
    }

    private static void handleUpdate(Connection conn, Scanner sc) throws SQLException {
        String idStr = sc.nextLine().trim();
        String field = sc.nextLine().trim();
        String value = sc.nextLine().trim();

        int custId = Integer.parseInt(idStr);

        String sql = "";
        if (field.equalsIgnoreCase("email")) {
            sql = "UPDATE Contacts SET email = ? WHERE cust_id = ?";
        } else if (field.equalsIgnoreCase("phone")) {
            sql = "UPDATE Contacts SET phone = ? WHERE cust_id = ?";
        } else {
            System.out.println("Invalid field");
            return;
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, value);
            stmt.setInt(2, custId);
            int updated = stmt.executeUpdate();
            if (updated > 0) {
                System.out.println("Contact updated successfully.");
            } else {
                System.out.println("Contact not found.");
            }
        }
    }

    private static void handleDelete(Connection conn, Scanner sc) throws SQLException {
        String idStr = sc.nextLine().trim();
        int custId = Integer.parseInt(idStr);

        String sql = "DELETE FROM Contacts WHERE cust_id = ?";
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, custId);
            int deleted = stmt.executeUpdate();
            if (deleted > 0) {
                System.out.println("Contact deleted successfully.");
            } else {
                System.out.println("Contact not found.");
            }
        }
    }

    private static void handleDisplay(Connection conn) throws SQLException {
        String sql = "SELECT cust_id, name, email, phone FROM Contacts";
        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {

            boolean hasResults = false;
            while (rs.next()) {
                hasResults = true;
                int id = rs.getInt("cust_id");
                String name = rs.getString("name");
                String email = rs.getString("email");
                String phone = rs.getString("phone");
                System.out.println(id + " " + name + " " + email + " " + phone);
            }

            if (!hasResults) {
                System.out.println("No contacts found.");
            }
        }
    }
}
